import { EOF, SEP, parseGrammar, ruleText, symbolList, type Problem, type Rule } from './grammar'
import type { ProjectData, Relation } from './project'

export type Prec = ProjectData['prec']
/** A relation of the table; '' = empty cell (syntax error). */
export type Rel = Relation | ''

const REL_CYCLE: Rel[] = ['', '<', '=', '>']
const key = (a: string, b: string) => a + SEP + b
const columnsOf = (terminals: readonly string[]) => (terminals.length ? [...terminals, EOF] : [])

/** Unique, non-empty terminals in their order, without $ (the table adds $ itself). */
export const normalizeTerminals = (terminals: readonly string[]) => [...new Set(terminals.filter((t) => t !== '' && t !== EOF))]

/** Terminals typed as text (separated by spaces, quoting like in rules). */
export const parseTerminals = (text: string) => normalizeTerminals(symbolList(text))

/** Number of rows (= columns) of the table including $; 0 without terminals. */
export const precTableSize = (prec: Pick<Prec, 'terminals'>) => columnsOf(normalizeTerminals(prec.terminals)).length

// Drops cells that refer to terminals no longer in the table.
function pruneCells(cells: Prec['cells'], terminals: readonly string[]) {
  const keep = new Set(columnsOf(terminals))
  return Object.fromEntries(
    Object.entries(cells).filter(([k]) => {
      const [a, b] = k.split(SEP)
      return keep.has(a) && keep.has(b)
    }),
  )
}

/** New terminal list (normalized); relations of removed terminals are dropped, the others are kept. */
export function setTerminals(prec: Prec, terminals: readonly string[]): Prec {
  const next = normalizeTerminals(terminals)
  return { ...prec, terminals: next, cells: pruneCells(prec.cells, next) }
}

/** Relation between the terminal on the stack (row) and the input token (column). */
export const relation = (prec: Pick<Prec, 'cells'>, stack: string, input: string): Rel => prec.cells[key(stack, input)] ?? ''

export function setRelation(prec: Prec, stack: string, input: string, rel: Rel): Prec {
  const cells = { ...prec.cells }
  if (rel) cells[key(stack, input)] = rel
  else delete cells[key(stack, input)]
  return { ...prec, cells }
}

/** Next relation in the order empty → < → = → > → empty (a click on the cell). */
export function cycleRelation(prec: Prec, stack: string, input: string): Prec {
  const rel = relation(prec, stack, input)
  return setRelation(prec, stack, input, REL_CYCLE[(REL_CYCLE.indexOf(rel) + 1) % REL_CYCLE.length])
}

export const clearRelations = (prec: Prec): Prec => ({ ...prec, cells: {} })

export interface PrecTable {
  /** Terminals of the table with $ last – the same list for rows and columns; [] without terminals. */
  columns: string[]
  rows: { terminal: string; relations: Rel[] }[]
}

export function precTable(prec: Prec): PrecTable {
  const columns = columnsOf(normalizeTerminals(prec.terminals))
  return { columns, rows: columns.map((terminal) => ({ terminal, relations: columns.map((c) => relation(prec, terminal, c)) })) }
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Checks and simulation share one parse of the reduction rules (analyzePrec); the empty-table hint no
//          longer points to the removed generator.
interface Reductions {
  rules: Rule[]
  errors: string[]
  /** First rule (1-based number) for each right side. */
  byRhs: Map<string, { rule: Rule; n: number }>
}

function parseReductions(text: string): Reductions {
  const { rules, errors } = parseGrammar(text)
  const byRhs = new Map<string, { rule: Rule; n: number }>()
  rules.forEach((rule, i) => {
    const k = rule.rhs.join(SEP)
    if (!byRhs.has(k)) byRhs.set(k, { rule, n: i + 1 })
  })
  return { rules, errors, byRhs }
}

function problemsOf(prec: Prec, red: Reductions): Problem[] {
  const probs: Problem[] = []
  const cols = columnsOf(normalizeTerminals(prec.terminals))
  red.errors.forEach((text) => probs.push({ level: 'bad', text }))
  const lhsSet = new Set(red.rules.map((r) => r.lhs))
  red.rules.forEach((r, i) => {
    if (!r.rhs.length) probs.push({ level: 'bad', text: `Pravidlo ${i + 1} je ε-pravidlo – precedenčná SA ich nepovoľuje` })
    const first = red.byRhs.get(r.rhs.join(SEP))!
    if (first.n !== i + 1) probs.push({ level: 'bad', text: `Pravidlá ${first.n} a ${i + 1} majú rovnakú pravú stranu (${r.rhs.join(' ')})` })
    r.rhs.forEach((s) => {
      if (!lhsSet.has(s) && !cols.includes(s)) probs.push({ level: 'warn', text: `Terminál ${s} z pravidla ${i + 1} nie je v tabuľke` })
    })
  })
  const filled = Object.keys(pruneCells(prec.cells, normalizeTerminals(prec.terminals))).length
  if (!cols.length) probs.push({ level: 'info', text: 'Zadaj terminály tabuľky alebo načítaj príklad.' })
  else {
    probs.push({
      level: 'info',
      text: `${cols.length}×${cols.length} tabuľka, vyplnených ${filled} buniek, prázdnych (= chyba) ${cols.length * cols.length - filled}`,
    })
  }
  if (cols.length && !red.rules.length) probs.push({ level: 'info', text: 'Bez redukčných pravidiel sa nedá simulovať.' })
  return probs
}

interface StackItem {
  /** t = terminal, n = nonterminal, m = the < marker */
  kind: 't' | 'n' | 'm'
  s: string
}

interface PrecTraceRow {
  stack: StackItem[]
  op: Rel
  input: string
  rule: string
}

export interface PrecSimulation {
  rows: PrecTraceRow[]
  ok: boolean
  message: string
}

function simulate(prec: Prec, red: Reductions): PrecSimulation | null {
  const toks = symbolList(prec.input)
  if (!toks.length || !red.rules.length) return null
  const start = red.rules[0].lhs
  const input = [...toks, EOF]
  const stack: StackItem[] = [{ kind: 't', s: EOF }]
  const rows: PrecTraceRow[] = []
  const output: number[] = []
  let pos = 0
  let result: { ok: boolean; message: string } | null = null
  for (let step = 0; step < 5000 && !result; step++) {
    let ti = stack.length - 1
    while (stack[ti].kind !== 't') ti--
    const a = stack[ti].s
    const b = input[pos]
    const row: PrecTraceRow = { stack: [...stack], op: '', input: input.slice(pos).join(' '), rule: '' }
    rows.push(row)
    if (b === EOF && stack.length === 2 && stack[1].kind === 'n' && stack[1].s === start) {
      // Slide 7 lists the rules in the order the reductions happened.
      result = { ok: true, message: `Úspech. Pravý rozbor: ${output.join(' ')}` }
      break
    }
    const rel = relation(prec, a, b)
    row.op = rel
    if (rel === '=') {
      stack.push({ kind: 't', s: b })
      pos++
    } else if (rel === '<') {
      stack.splice(ti + 1, 0, { kind: 'm', s: '<' })
      stack.push({ kind: 't', s: b })
      pos++
    } else if (rel === '>') {
      let mi = stack.length - 1
      while (mi >= 0 && stack[mi].kind !== 'm') mi--
      if (mi < 0) {
        result = { ok: false, message: 'Na zásobníku chýba <' }
        break
      }
      const y = stack.slice(mi + 1).map((it) => it.s)
      const r = red.byRhs.get(y.join(SEP))
      if (!r) {
        result = { ok: false, message: `Žiadne pravidlo s pravou stranou „${y.join(' ')}“` }
        break
      }
      stack.splice(mi, stack.length - mi, { kind: 'n', s: r.rule.lhs })
      output.push(r.n)
      row.rule = `${r.n}: ${ruleText(r.rule)}`
    } else {
      result = { ok: false, message: `Prázdna bunka [${a}, ${b}]` }
    }
  }
  return { rows, ...(result ?? { ok: false, message: 'Príliš veľa krokov' }) }
}

/** Checks of the table and its reduction rules, and the simulation of the input (null without input or rules). */
export function analyzePrec(prec: Prec): { problems: Problem[]; simulation: PrecSimulation | null } {
  const red = parseReductions(prec.rules)
  return { problems: problemsOf(prec, red), simulation: simulate(prec, red) }
}

/** Simulation of the precedence parse of prec.input (null without input or rules). */
export const simulatePrec = (prec: Prec) => simulate(prec, parseReductions(prec.rules))
